import{_ as d,o as e,c as o,a3 as c}from"./chunks/framework.BlfGB29P.js";const y=JSON.parse('{"title":"数据模型与实体约定","description":"","frontmatter":{},"headers":[],"relativePath":"cosmos/basic-app/architecture/data-model.md","filePath":"cosmos/basic-app/architecture/data-model.md","lastUpdated":1785868852000}'),a={name:"cosmos/basic-app/architecture/data-model.md"};function r(s,t,i,n,l,h){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="数据模型与实体约定" tabindex="-1">数据模型与实体约定 <a class="header-anchor" href="#数据模型与实体约定" aria-label="Permalink to &quot;数据模型与实体约定&quot;">​</a></h1><p>本页讲清 BasicApp 的<strong>数据层长什么样</strong>：实体基类怎么选、主键与并发怎么定、审计与软删有哪些列、多租户列的语义、分表规则、索引与命名规范，以及全部数据表的清单。新增实体前先读这页，能省掉大部分返工。</p><blockquote><p>数据访问的框架机制（仓储、工作单元、查询过滤器）见 <a href="./../../framework/packages/data">Data 包文档</a>；写路径的租户边界见 <a href="./../multi-tenancy">多租户</a>。</p></blockquote><h2 id="实体基类-先选对基类" tabindex="-1">实体基类：先选对基类 <a class="header-anchor" href="#实体基类-先选对基类" aria-label="Permalink to &quot;实体基类：先选对基类&quot;">​</a></h2><p>所有 BasicApp 实体都继承 <code>XiHan.BasicApp.Core.Entities</code> 下的基类，它们又各自对应框架的 <code>SugarMultiTenant*</code> 系列——<strong>都自带 <code>TenantId</code> 列</strong>。</p><table tabindex="0"><thead><tr><th>基类</th><th>主键</th><th>审计列</th><th>软删</th><th>用在哪</th></tr></thead><tbody><tr><td><code>BasicAppEntity</code></td><td>雪花 <code>long</code>（应用生成）</td><td>无</td><td>否</td><td>极简实体、纯关联表</td></tr><tr><td><code>BasicAppEntityWithIdentity</code></td><td>数据库自增 <code>long</code></td><td>无</td><td>否</td><td>需要自增序号的场景</td></tr><tr><td><code>BasicAppCreationEntity</code></td><td>雪花 <code>long</code></td><td>创建三列</td><td>否</td><td><strong>日志/流水</strong>等只增不改的表</td></tr><tr><td><code>BasicAppModificationEntity</code></td><td>雪花 <code>long</code></td><td>创建 + 修改</td><td>否</td><td>会改但不删的配置类</td></tr><tr><td><code>BasicAppDeletionEntity</code></td><td>雪花 <code>long</code></td><td>创建 + 删除</td><td>是</td><td>少见</td></tr><tr><td><strong><code>BasicAppFullAuditedEntity</code></strong></td><td>雪花 <code>long</code></td><td>创建 + 修改 + 删除</td><td><strong>是</strong></td><td><strong>绝大多数业务实体的默认选择</strong></td></tr><tr><td><code>BasicAppAggregateRoot</code></td><td>雪花 <code>long</code></td><td>全套</td><td>是</td><td>聚合根（带领域事件能力）</td></tr></tbody></table><p>选择准则：</p><ul><li><strong>拿不准就用 <code>BasicAppFullAuditedEntity</code></strong>——业务表几乎都需要「谁建的、谁改的、软删可恢复」。</li><li><strong>日志、流水、审计类用 <code>BasicAppCreationEntity</code></strong>：它们只增不改不删，带上修改/删除列纯属浪费，而且这类表通常还要<strong>按月分表</strong>。</li><li>纯多对多关联表（如 <code>SysUserRole</code>）通常也是创建型（硬删），见下文的软删约定。</li></ul><h2 id="列约定" tabindex="-1">列约定 <a class="header-anchor" href="#列约定" aria-label="Permalink to &quot;列约定&quot;">​</a></h2><h3 id="主键与并发" tabindex="-1">主键与并发 <a class="header-anchor" href="#主键与并发" aria-label="Permalink to &quot;主键与并发&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>Basic_Id</code></td><td><code>bigint</code></td><td><strong>主键</strong>。注意列名是 <code>Basic_Id</code> 而不是 <code>Id</code>——手写 SQL / 排查时别找错。默认<strong>非自增</strong>，由应用侧雪花算法生成</td></tr><tr><td><code>Row_Version</code></td><td><code>bigint</code></td><td>乐观并发标识，SqlSugar 的 <code>IsEnableUpdateVersionValidation</code> 生效</td></tr></tbody></table><p>雪花 ID 的参数在配置节 <code>XiHan:DistributedIds:SnowflakeId</code>（<code>WorkerId</code> / <code>DataCenterId</code> / <code>BaseTime</code> / 位长）。<strong>多节点部署必须逐节点改 <code>WorkerId</code></strong>，否则会生成重复 ID；<code>BaseTime</code> 与位长一经上线不可更改。</p><div class="warning custom-block"><p class="custom-block-title">主键在 API 里是字符串</p><p><code>long</code> 经框架的 <code>LongJsonConverter</code> 统一序列化成 JSON <strong>字符串</strong>（避免 JavaScript Number 精度溢出）。前端契约里主键类型是 <code>string</code>，DTO 字段名是 <code>basicId</code>。见 <a href="./../api-guide#json-序列化约定">接口对接指南</a>。</p></div><h3 id="审计三件套" tabindex="-1">审计三件套 <a class="header-anchor" href="#审计三件套" aria-label="Permalink to &quot;审计三件套&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>列</th><th>备注</th></tr></thead><tbody><tr><td>创建</td><td><code>Created_Time</code> / <code>Created_Id</code> / <code>Created_By</code></td><td><code>Created_Time</code> 非空；三列都是 <code>IsOnlyIgnoreUpdate</code>（更新时不覆盖）</td></tr><tr><td>修改</td><td><code>Modified_Time</code> / <code>Modified_Id</code> / <code>Modified_By</code></td><td>可空</td></tr><tr><td>删除</td><td><code>Is_Deleted</code> / <code>Deleted_Time</code> / <code>Deleted_Id</code> / <code>Deleted_By</code></td><td><code>Is_Deleted</code> 非空、默认 <code>false</code></td></tr></tbody></table><p>时间列都是 <code>DateTimeOffset</code>，<strong>存储恒为 UTC</strong>，输出时按请求头 <code>X-Timezone</code> 换算。这些列由 SqlSugar 的 <code>DataExecuting</code> AOP <strong>自动注入</strong>，业务代码不要手动赋值。</p><div class="warning custom-block"><p class="custom-block-title">别对时间列做单列标量投影</p><p><code>DateTimeOffset</code> 列不要用 <code>Select(x =&gt; x.CreatedTime)</code> 这种单列标量投影——值类型的 <code>ChangeType</code> 路径会在 <code>DateTime</code> → DTO 转换时崩。要整行取实体、走属性绑定。</p></div><h3 id="多租户列" tabindex="-1">多租户列 <a class="header-anchor" href="#多租户列" aria-label="Permalink to &quot;多租户列&quot;">​</a></h3><p><code>Tenant_Id</code>（<code>bigint</code>，<code>IsOnlyIgnoreUpdate</code>）是每个实体都有的列，语义<strong>不是可空的</strong>：</p><ul><li><strong>平台级/全局记录统一 <code>TenantId = 0</code></strong>（「平台租户」占位），<strong>不得使用 NULL</strong>。</li><li>业务租户 Id 从 1 开始分配，0 号由平台保留。</li><li>判定全局记录一律用 <code>TenantId == 0</code>；需要 <code>IsGlobal</code> 语义时在实体 <code>Expand</code> 里做<strong>派生只读属性</strong> <code>IsGlobal =&gt; TenantId == 0</code>，<strong>不落库</strong>（避免与 <code>TenantId</code> 漂移）。</li><li>合并查询全局 + 私有：<code>WHERE TenantId IN (0, {currentTenantId})</code>。</li><li><code>TenantId</code> 由租户上下文自动注入，<strong>禁止业务代码直接操纵</strong>。</li></ul><p>读写口径不对称，这点最容易踩：<strong>读共享、写不共享</strong>——全局过滤器放行 <code>TenantId=0</code> 的行让租户能读到平台数据，但租户上下文里<strong>禁止改写/删除</strong>非本租户行（含全局行）。维护全局数据的唯一合法入口是平台态（<code>ICurrentTenant.Change(null)</code>）。</p><h3 id="软删与唯一索引" tabindex="-1">软删与唯一索引 <a class="header-anchor" href="#软删与唯一索引" aria-label="Permalink to &quot;软删与唯一索引&quot;">​</a></h3><p>支持软删的实体（<code>FullAudited</code> / <code>AggregateRoot</code> 等），其<strong>唯一索引（<code>UX_*</code>）末列统一附加 <code>IsDeleted</code></strong>，使唯一性只约束未删除行——软删后可以再建同编码记录。</p><p>代价要知道：<strong>同一编码至多保留一条软删行</strong>。要第二次软删同编码记录，服务层得先物理清理旧的软删行。</p><p>纯创建型（<code>Creation</code>）的关联表与日志表是<strong>硬删</strong>、无 <code>IsDeleted</code>，唯一索引保持原样。</p><h2 id="命名与索引规范" tabindex="-1">命名与索引规范 <a class="header-anchor" href="#命名与索引规范" aria-label="Permalink to &quot;命名与索引规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>规范</th><th>示例</th></tr></thead><tbody><tr><td>表名</td><td><code>snake_case</code>，<code>Sys_{名}</code></td><td><code>Sys_User_Department</code></td></tr><tr><td>列名</td><td><code>snake_case</code></td><td><code>Created_Time</code>、<code>Tenant_Id</code></td></tr><tr><td><code>[SugarTable]</code> 命名参数</td><td><strong>无空格</strong></td><td><code>SugarTable(TableName = &quot;...&quot;, TableDescription = &quot;...&quot;)</code></td></tr><tr><td><code>[SugarColumn]</code> 命名参数</td><td><strong>有空格</strong></td><td><code>SugarColumn(ColumnName = &quot;...&quot;, ColumnDescription = &quot;...&quot;)</code></td></tr><tr><td>时间字段</td><td>一律 <code>XxxTime</code>；过期统一 <code>ExpirationTime</code></td><td><code>CreatedTime</code> / <code>ExpirationTime</code></td></tr><tr><td>排序字段</td><td><code>Sort</code></td><td>—</td></tr><tr><td>缩写</td><td><code>OAuth</code> / <code>CSharp</code> 等整体保留</td><td><code>SysOAuthApp</code></td></tr></tbody></table><p><strong>审计三件套索引</strong>（强制）：</p><ul><li>所有具体实体：<code>IX_{table}_TeId_CrTi</code>、<code>IX_{table}_CrId</code></li><li><code>FullAudited</code> / <code>AggregateRoot</code> 额外：<code>IX_{table}_TeId_IsDe</code></li><li>日志类分表实体把 <code>{table}</code> 换成 <code>{split_table}</code></li></ul><h2 id="按月分表" tabindex="-1">按月分表 <a class="header-anchor" href="#按月分表" aria-label="Permalink to &quot;按月分表&quot;">​</a></h2><p>日志与流水类实体用 SqlSugar 的分表能力：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SugarTable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">TableName</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Sys_Access_Log_{year}{month}{day}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">TableDescription</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;系统访问日志表&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SplitTable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SplitType.Month)]</span></span></code></pre></div><p>物理表名形如 <code>Sys_Access_Log_20260801</code>。当前按月分表的表：</p><p><code>Sys_Access_Log</code> · <code>Sys_OpenApi_Log</code> · <code>Sys_Operation_Log</code> · <code>Sys_Login_Log</code> · <code>Sys_Exception_Log</code> · <code>Sys_Diff_Log</code> · <code>Sys_Permission_Change_Log</code> · <code>Sys_Review_Log</code> · <code>Sys_Task_Log</code> · <code>Sys_Telegram_Message</code></p><p>查询分表数据要走 SqlSugar 的分表 API（按时间范围定位物理表），不能当普通表直接查。</p><h2 id="数据表清单" tabindex="-1">数据表清单 <a class="header-anchor" href="#数据表清单" aria-label="Permalink to &quot;数据表清单&quot;">​</a></h2><p>按域分组的全部业务表（不含日志分表的物理分片）。</p><h3 id="身份与安全" tabindex="-1">身份与安全 <a class="header-anchor" href="#身份与安全" aria-label="Permalink to &quot;身份与安全&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_User</code></td><td><code>SysUser</code></td><td>用户主体，<code>Email</code> 全平台唯一</td></tr><tr><td><code>Sys_User_Security</code></td><td><code>SysUserSecurity</code></td><td>一对一安全扩展：密码哈希、锁定、MFA、多端策略</td></tr><tr><td><code>Sys_User_Session</code></td><td><code>SysUserSession</code></td><td>会话中心（多端控制、撤销）</td></tr><tr><td><code>Sys_User_Setting</code></td><td><code>SysUserSetting</code></td><td>用户 UI 偏好（按场景 + key 存 JSON）</td></tr><tr><td><code>Sys_User_Statistics</code></td><td><code>SysUserStatistics</code></td><td>用户统计</td></tr><tr><td><code>Sys_User_Api_Credential</code></td><td><code>SysUserApiCredential</code></td><td>开放接口个人凭证（AppKey/AppSecret 哈希）</td></tr><tr><td><code>Sys_External_Login</code></td><td><code>SysExternalLogin</code></td><td>第三方身份绑定</td></tr><tr><td><code>Sys_Password_History</code></td><td><code>SysPasswordHistory</code></td><td>历史密码（防重用）</td></tr></tbody></table><h3 id="权限与授权" tabindex="-1">权限与授权 <a class="header-anchor" href="#权限与授权" aria-label="Permalink to &quot;权限与授权&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_Role</code> / <code>Sys_Role_Hierarchy</code></td><td><code>SysRole</code> / <code>SysRoleHierarchy</code></td><td>角色与层级继承（闭包）</td></tr><tr><td><code>Sys_Permission</code></td><td><code>SysPermission</code></td><td>权限点</td></tr><tr><td><code>Sys_Operation</code> / <code>Sys_Resource</code></td><td><code>SysOperation</code> / <code>SysResource</code></td><td>操作字典与资源，<strong>权限由「资源 × 操作」派生</strong></td></tr><tr><td><code>Sys_Role_Permission</code> / <code>Sys_User_Permission</code></td><td>—</td><td>角色授权 / 用户直授</td></tr><tr><td><code>Sys_Role_Data_Scope</code> / <code>Sys_User_Data_Scope</code></td><td>—</td><td>自定义数据范围</td></tr><tr><td><code>Sys_Permission_Condition</code></td><td><code>SysPermissionCondition</code></td><td>ABAC 属性条件</td></tr><tr><td><code>Sys_Permission_Delegation</code></td><td><code>SysPermissionDelegation</code></td><td>权限委托</td></tr><tr><td><code>Sys_Permission_Request</code></td><td><code>SysPermissionRequest</code></td><td>权限申请</td></tr><tr><td><code>Sys_Field_Level_Security</code></td><td><code>SysFieldLevelSecurity</code></td><td>字段级安全（可读/可编辑/脱敏策略）</td></tr><tr><td><code>Sys_Constraint_Rule</code> / <code>Sys_Constraint_Rule_Item</code></td><td>—</td><td>约束规则引擎（SSD/DSD/互斥/基数…）</td></tr><tr><td><code>Sys_Session_Role</code></td><td><code>SysSessionRole</code></td><td>会话角色映射</td></tr></tbody></table><h3 id="组织与租户" tabindex="-1">组织与租户 <a class="header-anchor" href="#组织与租户" aria-label="Permalink to &quot;组织与租户&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_Department</code> / <code>Sys_Department_Hierarchy</code></td><td>—</td><td>部门树与<strong>闭包表</strong></td></tr><tr><td><code>Sys_Position</code></td><td><code>SysPosition</code></td><td>岗位字典</td></tr><tr><td><code>Sys_User_Department</code></td><td><code>SysUserDepartment</code></td><td>用户多部门归属（主部门、岗位、工号）</td></tr><tr><td><code>Sys_User_Role</code></td><td><code>SysUserRole</code></td><td>用户角色（支持生效期）</td></tr><tr><td><code>Sys_Tenant</code></td><td><code>SysTenant</code></td><td>租户</td></tr><tr><td><code>Sys_Tenant_User</code></td><td><code>SysTenantUser</code></td><td>租户成员关系</td></tr><tr><td><code>Sys_Tenant_Edition</code> / <code>Sys_Tenant_Edition_Permission</code></td><td>—</td><td>版本套餐与可用权限白名单</td></tr></tbody></table><h3 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_Menu</code></td><td><code>SysMenu</code></td><td>菜单（<code>PageRegistry</code> 的落库形态）</td></tr><tr><td><code>Sys_Dict</code> / <code>Sys_Dict_Item</code></td><td>—</td><td>数据字典</td></tr><tr><td><code>Sys_Config</code></td><td><code>SysConfig</code></td><td>参数配置</td></tr><tr><td><code>Sys_Numbering_Rule</code> / <code>Sys_Numbering_Allocation</code></td><td>—</td><td>业务编号规则与分配记录</td></tr><tr><td><code>Sys_Version</code></td><td><code>SysVersion</code></td><td>版本管理</td></tr><tr><td><code>Sys_Migration_History</code></td><td><code>SysMigrationHistory</code></td><td>升级迁移历史</td></tr></tbody></table><h3 id="消息与通知" tabindex="-1">消息与通知 <a class="header-anchor" href="#消息与通知" aria-label="Permalink to &quot;消息与通知&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_Notification</code> / <code>Sys_User_Notification</code></td><td>—</td><td>通知公告与逐用户接收状态</td></tr><tr><td><code>Sys_User_Notification_Preference</code></td><td>—</td><td>通知偏好（渠道 × 类型）</td></tr><tr><td><code>Sys_Message_Template</code></td><td><code>SysMessageTemplate</code></td><td>消息模板（Scriban）</td></tr><tr><td><code>Sys_Email</code> / <code>Sys_Email_Config</code></td><td>—</td><td>邮件记录与网关配置</td></tr><tr><td><code>Sys_Sms</code> / <code>Sys_Sms_Config</code></td><td>—</td><td>短信记录与网关配置</td></tr><tr><td><code>Sys_Bot_Config</code></td><td><code>SysBotConfig</code></td><td>钉钉/飞书/企业微信 Webhook 机器人</td></tr><tr><td><code>Sys_Telegram_Bot</code></td><td><code>SysTelegramBot</code></td><td>多实例 Telegram Bot</td></tr><tr><td><code>Sys_Chat_Conversation</code> / <code>_Member</code> / <code>Sys_Chat_Message</code> / <code>_Reaction</code></td><td>—</td><td>在线聊天</td></tr></tbody></table><h3 id="文件与任务" tabindex="-1">文件与任务 <a class="header-anchor" href="#文件与任务" aria-label="Permalink to &quot;文件与任务&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_File</code> / <code>Sys_File_Storage</code></td><td>—</td><td>文件与存储位置</td></tr><tr><td><code>Sys_Storage_Config</code></td><td><code>SysStorageConfig</code></td><td>存储后端配置（本地/S3/OSS/COS/MinIO）</td></tr><tr><td><code>Sys_Export_Task</code></td><td><code>SysExportTask</code></td><td>异步导出任务</td></tr><tr><td><code>Sys_Import_History</code></td><td><code>SysImportHistory</code></td><td>导入历史</td></tr><tr><td><code>Sys_Task</code></td><td><code>SysTask</code></td><td>定时任务定义</td></tr></tbody></table><h3 id="开放能力与审批" tabindex="-1">开放能力与审批 <a class="header-anchor" href="#开放能力与审批" aria-label="Permalink to &quot;开放能力与审批&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_OAuth_App</code> / <code>Sys_OAuth_Code</code> / <code>Sys_OAuth_Token</code></td><td>—</td><td>作为 OAuth2/OIDC <strong>服务端</strong>的应用、授权码与令牌</td></tr><tr><td><code>Sys_Review</code></td><td><code>SysReview</code></td><td>审批/审查单</td></tr></tbody></table><h3 id="工作流-xihan-basicapp-workflow-模块" tabindex="-1">工作流（<code>XiHan.BasicApp.Workflow</code> 模块） <a class="header-anchor" href="#工作流-xihan-basicapp-workflow-模块" aria-label="Permalink to &quot;工作流（`XiHan.BasicApp.Workflow` 模块）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_Workflow_Definition</code></td><td><code>SysWorkflowDefinition</code></td><td>流程定义</td></tr><tr><td><code>Sys_Workflow_Instance</code></td><td><code>SysWorkflowInstance</code></td><td>流程实例</td></tr><tr><td><code>Sys_Workflow_Node_Instance</code></td><td><code>SysWorkflowNodeInstance</code></td><td>节点实例</td></tr><tr><td><code>Sys_Workflow_Bookmark</code></td><td><code>SysWorkflowBookmark</code></td><td>书签（挂起点）</td></tr></tbody></table><h3 id="日志-均按月分表" tabindex="-1">日志（均按月分表） <a class="header-anchor" href="#日志-均按月分表" aria-label="Permalink to &quot;日志（均按月分表）&quot;">​</a></h3><p><code>Sys_Access_Log</code>（访问）· <code>Sys_OpenApi_Log</code>（开放接口）· <code>Sys_Operation_Log</code>（操作）· <code>Sys_Login_Log</code>（登录）· <code>Sys_Exception_Log</code>（异常）· <code>Sys_Diff_Log</code>（数据变更）· <code>Sys_Permission_Change_Log</code>（权限变更）· <code>Sys_Review_Log</code>（审批）· <code>Sys_Task_Log</code>（任务）· <code>Sys_Telegram_Message</code>（Telegram 出站审计）</p><p>详见 <a href="./../audit-log">审计日志</a>。</p><h2 id="建表与迁移" tabindex="-1">建表与迁移 <a class="header-anchor" href="#建表与迁移" aria-label="Permalink to &quot;建表与迁移&quot;">​</a></h2><ul><li>首次启动由 <code>DbInitializer</code> 自动建库、建表、播种（配置节 <code>XiHan:Data:SqlSugarCore</code> 的 <code>EnableDbInitialization</code> / <code>EnableTableInitialization</code> / <code>EnableDataSeeding</code>）。</li><li><strong><code>DbInitializer</code> 表存在就跳过，从不为已有表补列</strong>。给既有实体加字段后部署必报「列不存在」。</li><li>本项目的策略是<strong>部署即重建数据库、前向单一格式、不写向后兼容代码</strong>。要保数据就自己 <code>ALTER TABLE</code>。</li></ul><h2 id="实体分文件约定" tabindex="-1">实体分文件约定 <a class="header-anchor" href="#实体分文件约定" aria-label="Permalink to &quot;实体分文件约定&quot;">​</a></h2><p>一个实体通常拆成三个文件（<code>partial</code>）：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>Domain/Entities/SysXxx.cs</code></td><td>主体：<code>[SugarTable]</code> + <code>[SugarIndex]</code> + 落库字段</td></tr><tr><td><code>Domain/Entities/Expands/SysXxx.Expand.cs</code></td><td><strong>不落库</strong>的派生属性（<code>[SugarColumn(IsIgnore = true)]</code>），如 <code>IsGlobal</code>、显示名</td></tr><tr><td><code>Domain/Entities/Aggregates/SysXxx.Aggregate.cs</code></td><td>聚合行为（少数实体才有，如 <code>SysTenant</code> / <code>SysConstraintRule</code>）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">生成的代码不焊外键</p><p>代码生成器不产出 <code>Navigate</code> / <code>LEFT JOIN</code> / 显示属性 / 物理外键，跨表关联一律由业务层手写。见 <a href="./../code-generation">代码生成</a>。</p></div><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./backend">后端架构</a>：模块装配、DDD 分层、DI 约定</li><li><a href="./caching-async">缓存与异步</a>：读路径缓存与写后失效</li><li><a href="./../multi-tenancy">多租户与版本</a>：隔离策略与写路径边界</li><li><a href="./../audit-log">审计日志</a>：七类日志与分表</li><li><a href="./../../framework/packages/data">Data 包文档</a>：仓储、查询过滤器、AOP 的框架实现</li></ul>',64)])])}const g=d(a,[["render",r]]);export{y as __pageData,g as default};
